//! 🎟️ Exact retained-work grants preserve shared contour geometry and actual allocator effects.
use super::*;
use semio_framework_value::{RetainedCloneGrant,RetainedCloneProgress,RetirementDemand};
use semio_framework_value_persistent::work::RetainedWorkLedger;
use semio_framework_trace::observe_heap_allocations_on_this_thread as observe;
#[global_allocator]
static HEAP:semio_framework_trace::HeapWitness=semio_framework_trace::HeapWitness;
fn remaining(stock:RetainedCloneGrant,p:RetainedCloneProgress)->RetainedCloneGrant{assert!(p.fits(stock));RetainedCloneGrant{maximum_items:stock.maximum_items-p.copied_items,maximum_copy_bytes:stock.maximum_copy_bytes-p.copied_bytes,maximum_capacity_bytes:stock.maximum_capacity_bytes-p.retained_capacity_bytes,maximum_release_bytes:stock.maximum_release_bytes-p.released_bytes,..stock}}
fn quote(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn admitted(g:RetainedCloneGrant,s:RetainedCloneGrant){assert!(g.maximum_items<=s.maximum_items&&g.maximum_copy_bytes<=s.maximum_copy_bytes&&g.maximum_capacity_bytes<=s.maximum_capacity_bytes&&g.maximum_release_bytes<=s.maximum_release_bytes&&g.maximum_depth<=s.maximum_depth);}
#[test]
fn exact_five_axis_work_preserves_shared_contours_and_actual_backing(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let mut denied=[false;5];
 for row in fixtures().as_array().unwrap(){
  let mut stock=RetainedCloneGrant{maximum_items:law["items"].as_u64().unwrap()as usize,maximum_copy_bytes:law["copy"].as_u64().unwrap()as usize,maximum_capacity_bytes:law["capacity"].as_u64().unwrap()as usize,maximum_release_bytes:law["release"].as_u64().unwrap()as usize,maximum_depth:law["depth"].as_u64().unwrap()as usize};
  let mut job=PathFlattenJob::new(input(row));let source=job.input.segments.as_ptr();let mut completed=false;
  for _ in 0..law["maxTurns"].as_u64().unwrap(){
   let d=job.next_work_demand();let g=quote(d);assert!(g.maximum_items<=stock.maximum_items&&g.maximum_copy_bytes<=stock.maximum_copy_bytes&&g.maximum_capacity_bytes<=stock.maximum_capacity_bytes&&g.maximum_release_bytes<=stock.maximum_release_bytes&&g.maximum_depth<=stock.maximum_depth);
   for axis in 0..5{if denied[axis]||match axis{0=>false,1=>d.copy_bytes==0,2=>d.capacity_bytes==0,3=>d.release_bytes==0,_=>d.depth==0}{continue;}let mut no=g;match axis{0=>no.maximum_items=0,1=>no.maximum_copy_bytes-=1,2=>no.maximum_capacity_bytes-=1,3=>no.maximum_release_bytes-=1,_=>no.maximum_depth-=1}let mut work=RetainedWorkLedger::new(no);let before=job.work;let(result,heap)=funding::with_effect(no,funding::WORK,&mut None,|effect|observe(||job.advance(1,&mut work,effect)));let progress=result.unwrap();assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(work.receipt(),Default::default());assert_eq!(job.last_turn_work(),0);assert_eq!(progress.work,before);assert!(!progress.done);assert_eq!(job.input.segments.as_ptr(),source);denied[axis]=true;}
   let mut work=RetainedWorkLedger::new(g);let before=job.work;let(result,heap)=funding::with_effect(g,funding::WORK,&mut None,|effect|observe(||job.advance(1,&mut work,effect)));let progress=result.unwrap();let p=work.receipt();assert!(!heap.overflowed);assert!(p.fits(g));assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));assert_eq!(progress.work-before,job.last_turn_semantic_work());assert!(job.last_turn_semantic_work()<=job.last_turn_work());if p!=Default::default(){assert!(job.last_turn_work()>0);}assert_eq!(job.input.segments.as_ptr(),source);stock=remaining(stock,p);if progress.done{completed=true;break;}
  }
  assert!(completed);let expected=row["expected"].as_array().unwrap();let actual=job.result().unwrap();assert_eq!(actual.len(),expected.len());for(contour,e)in actual.iter().zip(expected){assert_eq!(contour.closed,e["closed"].as_bool().unwrap());let points=e["points"].as_array().unwrap();assert_eq!(contour.points.len(),points.len());for(p,e)in contour.points.iter().zip(points){for axis in 0..2{assert!((p[axis]-e[axis].as_f64().unwrap()).abs()<1e-10);}}}
  let(mut closing,output)=job.into_retirement();let mut retained=semio_framework_value::retirement::controlled::ControlledRetirement::retain(output);for _ in 0..law["maxTurns"].as_u64().unwrap(){if closing.terminal_is_empty(){break;}let g=funding::quoted(1,|body|closing.next_demand(body).unwrap());admitted(g,stock);let(result,heap)=funding::with_effect(g,funding::WORK,&mut None,|effect|observe(||funding::settled(closing.close_step(g.maximum_copy_bytes,effect)).result));let p=result.unwrap().progress();assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));stock=remaining(stock,p);}assert!(closing.terminal_is_empty());let((),heap)=observe(||drop(closing));assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
  for _ in 0..law["maxTurns"].as_u64().unwrap(){if retained.terminal_is_empty(){break;}let d=retained.next_demand(32768).unwrap();let g=quote(d);admitted(g,stock);let(result,heap)=funding::with_effect(g,funding::WORK,&mut None,|effect|observe(||funding::settled(retained.step(32768,effect)).result));let p=result.unwrap().progress();assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));stock=remaining(stock,p);}assert!(retained.terminal_is_empty());
 }
 assert!(denied.into_iter().all(|axis|axis));
}

#[test]
fn funded_contours_paint_the_same_output_as_independent_tiny_skia_geometry(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let reference=&law["reference"];let width=reference["width"].as_u64().unwrap()as u32;let height=reference["height"].as_u64().unwrap()as u32;let points:Vec<[f64;2]>=serde_json::from_value(reference["points"].clone()).unwrap();let mut source=Vec::new();source.push(PathSegment::Move{to:points[0]});for point in &points[1..]{source.push(PathSegment::Line{to:*point});}source.push(PathSegment::Close);
 let mut job=funded(PathFlattenInput{segments:source,transform:[1.,0.,0.,1.,0.,0.],tolerance:0.1});let mut done=false;for _ in 0..job.turn_bound(){if job.turn(1,|job,work,alloc|job.advance(1,work,alloc)).unwrap().done{done=true;break}}assert!(done);let mut actual=tiny_skia::Pixmap::new(width,height).unwrap();let mut path=tiny_skia::PathBuilder::new();for contour in job.result().unwrap(){if let Some(first)=contour.points.first(){path.move_to(first[0]as f32,first[1]as f32);for point in &contour.points[1..]{path.line_to(point[0]as f32,point[1]as f32);}if contour.closed{path.close();}}}
 let mut paint=tiny_skia::Paint::default();paint.set_color_rgba8(255,255,255,255);actual.fill_path(&path.finish().unwrap(),&paint,tiny_skia::FillRule::Winding,tiny_skia::Transform::identity(),None);let mut independent=tiny_skia::Pixmap::new(width,height).unwrap();let mut rectangle=tiny_skia::PathBuilder::new();rectangle.push_rect(tiny_skia::Rect::from_xywh(0.,0.,width as f32,height as f32).unwrap());independent.fill_path(&rectangle.finish().unwrap(),&paint,tiny_skia::FillRule::Winding,tiny_skia::Transform::identity(),None);assert_eq!(actual.data(),independent.data());assert_eq!(actual.data(),serde_json::from_value::<Vec<u8>>(reference["rgba"].clone()).unwrap());job.finish();
}
